solution.solution.cpp:
#include <optional>
#include <string>
#include <string_view>
#include <vector>

struct DocParam { std::string name; std::string text; };
struct DocComment
{
    std::string summary;
    std::vector<DocParam> params;
    std::string returns;
    std::vector<std::string> throws;
};

namespace
{
    std::string_view trimLeft(std::string_view s)
    {
        while (!s.empty() && (s.front() == ' ' || s.front() == '\t')) s.remove_prefix(1);
        return s;
    }

    std::string_view trimRight(std::string_view s)
    {
        while (!s.empty() && (s.back() == ' ' || s.back() == '\t')) s.remove_suffix(1);
        return s;
    }

    bool identChar(char c)
    {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_';
    }

    bool declares(std::string_view line, std::string_view name)
    {
        if (trimLeft(line).starts_with("//")) return false;
        for (std::size_t at{ line.find(name) }; at != std::string_view::npos; at = line.find(name, at + 1))
        {
            if (at > 0 && identChar(line[at - 1])) continue;
            const std::string_view after{ trimLeft(line.substr(at + name.size())) };
            if (!after.empty() && after.front() == '(') return true;
        }
        return false;
    }

    void append(std::string& target, std::string_view text)
    {
        if (text.empty()) return;
        if (!target.empty()) target += ' ';
        target += text;
    }
}

std::optional<DocComment> docFor(std::string_view source, std::string_view functionName)
{
    std::vector<std::string_view> lines;
    for (std::size_t at{ 0 }; at <= source.size();)
    {
        std::size_t end{ source.find('\n', at) };
        if (end == std::string_view::npos) end = source.size();
        std::string_view line{ source.substr(at, end - at) };
        if (!line.empty() && line.back() == '\r') line.remove_suffix(1);
        lines.push_back(line);
        at = end + 1;
    }

    std::size_t decl{ 0 };
    while (decl < lines.size() && !declares(lines[decl], functionName)) ++decl;
    if (decl == lines.size()) return std::nullopt;

    std::size_t first{ decl };
    while (first > 0 && trimLeft(lines[first - 1]).starts_with("///")) --first;

    DocComment doc;
    std::string* current{ &doc.summary };
    for (std::size_t i{ first }; i < decl; ++i)
    {
        const std::string_view text{ trimRight(trimLeft(trimLeft(lines[i]).substr(3))) };
        if (text.empty()) continue;
        if (text.front() == '@')
        {
            std::size_t space{ text.find(' ') };
            const std::string_view tag{ text.substr(0, space) };
            std::string_view rest{ space == std::string_view::npos ? std::string_view{} : trimLeft(text.substr(space + 1)) };
            if (tag == "@param")
            {
                space = rest.find(' ');
                const std::string_view name{ rest.substr(0, space) };
                const std::string_view description{ space == std::string_view::npos ? std::string_view{} : trimLeft(rest.substr(space + 1)) };
                doc.params.push_back({ std::string(name), std::string(description) });
                current = &doc.params.back().text;
            }
            else if (tag == "@return" || tag == "@returns")
            {
                doc.returns = std::string(rest);
                current = &doc.returns;
            }
            else if (tag == "@throws")
            {
                doc.throws.emplace_back(rest);
                current = &doc.throws.back();
            }
            else
            {
                current = nullptr;
            }
            continue;
        }
        if (current) append(*current, text);
    }
    return doc;
}

std::vector<std::string> missingParams(const DocComment& doc, const std::vector<std::string>& parameterNames)
{
    std::vector<std::string> missing;
    for (const std::string& name : parameterNames)
    {
        bool found{ false };
        for (const DocParam& p : doc.params) if (p.name == name) found = true;
        if (!found) missing.push_back(name);
    }
    return missing;
}

unitTests:
const char* kSource{ R"(#include <string>

/// Reads a whole file into memory.
///
/// Missing files are not an error.
/// @param path  the file to read;
///              relative to the working directory.
/// @param mode how to open it
/// @return the contents, or std::nullopt
///   if the file cannot be read.
/// @throws std::bad_alloc if it does not fit in memory
/// @since 2.1
/// this line belongs to the unknown tag
std::optional<std::string> readWholeFile(const std::string& path, int mode);

// A plain comment, not documentation.
int helper(int x);

/// Adds two numbers.
int add (int a, int b);
int unreadWholeFile(int);
)" };
TEST("a full comment") {
    const auto doc{ docFor(kSource, "readWholeFile") };
    CHECK(doc.has_value());
    if (!doc) return;
    CHECK_EQ(doc->summary, std::string("Reads a whole file into memory. Missing files are not an error."));
    CHECK_EQ(doc->params.size(), 2u);
    if (doc->params.size() == 2) {
        CHECK_EQ(doc->params[0].name, std::string("path"));
        CHECK_EQ(doc->params[0].text, std::string("the file to read; relative to the working directory."));
        CHECK_EQ(doc->params[1].name, std::string("mode"));
        CHECK_EQ(doc->params[1].text, std::string("how to open it"));
    }
    CHECK_EQ(doc->returns, std::string("the contents, or std::nullopt if the file cannot be read."));
    CHECK(doc->throws == (std::vector<std::string>{ "std::bad_alloc if it does not fit in memory" }));
}
TEST("short comments and none") {
    const auto add{ docFor(kSource, "add") };
    CHECK(add.has_value() && add->summary == "Adds two numbers." && add->params.empty() && add->returns.empty());
    const auto helper{ docFor(kSource, "helper") };
    CHECK(helper.has_value() && helper->summary.empty() && helper->params.empty());
    CHECK(!docFor(kSource, "missing").has_value());
    const auto unread{ docFor(kSource, "unreadWholeFile") };
    CHECK(unread.has_value() && unread->summary.empty());
}
TEST("windows line endings and returns") {
    const auto doc{ docFor("/// Sums.\r\n/// @returns the sum\r\nint sum(int a);\r\n", "sum") };
    CHECK(doc.has_value() && doc->summary == "Sums." && doc->returns == "the sum");
}
TEST("undocumented parameters") {
    const auto doc{ docFor(kSource, "readWholeFile") };
    CHECK(doc.has_value());
    if (doc) {
        CHECK(missingParams(*doc, { "path", "mode" }).empty());
        CHECK(missingParams(*doc, { "path", "flags", "mode", "size" }) == (std::vector<std::string>{ "flags", "size" }));
    }
    CHECK(missingParams(DocComment{}, { "a" }) == (std::vector<std::string>{ "a" }));
}

